package com.aistock.prediction.forecast;
import com.aistock.common.BusinessException;import com.aistock.prediction.modelcatalog.ModelRecords.Version;import com.fasterxml.jackson.databind.*;
import java.time.LocalDate;import java.util.*;
public final class HttpForecastDependencies implements ForecastDependencies {
 private final String market,algorithm;private final BoundedForecastHttp http;private final java.util.function.Consumer<UUID> beforePreparationRequest;
 public HttpForecastDependencies(String market,String algorithm,String token,ObjectMapper mapper){this(market,algorithm,token,mapper,operation->{});}
 public HttpForecastDependencies(String market,String algorithm,String token,ObjectMapper mapper,java.util.function.Consumer<UUID> beforePreparationRequest){this.market=market;this.algorithm=algorithm;this.http=new BoundedForecastHttp(token,mapper);this.beforePreparationRequest=Objects.requireNonNull(beforePreparationRequest);}
 private JsonNode prepareCall(UUID operation,String base,String path,Object body,int seconds){
  beforePreparationRequest.accept(operation);
  return http.call(base,path,body,seconds);
 }
 private JsonNode data(JsonNode envelope){if(!"OK".equals(envelope.path("code").asText())||!envelope.path("data").isObject())throw BoundedForecastHttp.error("PREDICTION_DEPENDENCY_UNAVAILABLE");return envelope.get("data");}
 public JsonNode prepare(String stock,UUID operation){JsonNode window;try{window=data(prepareCall(operation,market,"/internal/v1/market/forecast-window?instrumentId="+stock,null,10));}catch(BusinessException e){if(!"FORECAST_INPUT_NOT_AVAILABLE".equals(e.code()))throw e;var raw=data(prepareCall(operation,market,"/internal/v1/market/forecast-raw-window?instrumentId="+stock,null,10));var bars=raw.path("bars");if(!"AVAILABLE".equals(raw.path("state").asText())||!"baostock".equals(raw.path("provider").asText())||!"RAW".equals(raw.path("priceBasis").asText())||!bars.isArray()||bars.isEmpty()||!ForecastService.uuid(raw.path("versionId").asText()))throw BoundedForecastHttp.error("MODEL_INPUT_INCOMPATIBLE");var end=LocalDate.parse(bars.get(bars.size()-1).path("date").asText());var collect=prepareCall(operation,algorithm,"/internal/v1/market/forecast-collect",Map.of("operationId",operation.toString(),"instrumentId",stock,"rawVersionId",raw.path("versionId").asText(),"start",bars.get(0).path("date").asText(),"end",end.toString(),"calendarThrough",end.plusDays(40).toString()),35);if(!"AVAILABLE".equals(collect.path("state").asText())||!collect.path("candidate").isObject())throw BoundedForecastHttp.error(safeState(collect));var published=data(prepareCall(operation,market,"/internal/v1/market/forecast-inputs",collect.get("candidate"),10));var input=published.path("inputVersionId").asText();if(!ForecastService.uuid(input))throw BoundedForecastHttp.error("MODEL_INPUT_INCOMPATIBLE");window=data(prepareCall(operation,market,"/internal/v1/market/forecast-window?instrumentId="+stock+"&inputVersionId="+input,null,10));}
  if(!stock.equals(window.path("instrumentId").asText())||!"FRESH".equals(window.path("freshness").asText())||!ForecastService.uuid(window.path("inputVersionId").asText()))throw BoundedForecastHttp.error("MODEL_INPUT_NOT_CURRENT");var current=data(prepareCall(operation,market,"/internal/v1/market/forecast-window?instrumentId="+stock,null,10));if(!current.path("rawVersionId").equals(window.path("rawVersionId"))||!current.path("inputVersionId").equals(window.path("inputVersionId"))||!current.path("inputHash").equals(window.path("inputHash"))||!"FRESH".equals(current.path("freshness").asText()))throw BoundedForecastHttp.error("MODEL_INPUT_NOT_CURRENT");return window;
 }
 public JsonNode infer(Version model,JsonNode window){var reply=http.call(algorithm,"/internal/v1/infer",Map.of("modelId",model.modelId().toString(),"artifactId",model.artifactId(),"manifestHash",model.manifestHash(),"instrumentId",window.path("instrumentId").asText(),"inputVersionId",window.path("inputVersionId").asText()),50);if(!"AVAILABLE".equals(reply.path("state").asText())||!reply.path("result").isObject())throw BoundedForecastHttp.error(safeState(reply));return reply.get("result");}
 private String safeState(JsonNode reply){var code=reply.path("state").asText();return Set.of("MODEL_MARKET_USE_INVALID","SOURCE_BUSY","SOURCE_UNAVAILABLE","SOURCE_TIMEOUT","SOURCE_INVALID","MODEL_NOT_PUBLISHED","MODEL_INPUT_NOT_CURRENT","MODEL_INPUT_INCOMPATIBLE","MODEL_INPUT_UNAVAILABLE","MODEL_PUBLICATION_UNAVAILABLE","MODEL_PUBLICATION_MISMATCH","MODEL_VALIDATION_BUSY","MODEL_VALIDATION_TIMEOUT","MODEL_WORKER_INVALID","MODEL_OUTPUT_INVALID","MODEL_ARTIFACT_INVALID").contains(code)?code:"PREDICTION_DEPENDENCY_UNAVAILABLE";}
}
